class Solution {
public:
    bool phonePrefix(vector<string>& numbers) {
        sort(numbers.begin(), numbers.end());
        for (int i = 1; i < (int)numbers.size(); ++i) {
            const string& a = numbers[i - 1];
            const string& b = numbers[i];
            if (b.compare(0, a.size(), a) == 0) return false;
        }
        return true;
    }
};
